sys_script_include.script:
var BudgetUtils = Class.create();
BudgetUtils.prototype = {
    initialize: function() {
    },


    calculateTotalBudget: function(eventId) {
        var total = 0;
        var gr = new GlideRecord('Budget'); 
        gr.addQuery('u_event_id', eventId); 
        gr.query();
        while (gr.next()) {
            total += parseFloat(gr.u_total_budget || 0);
        }
        return total;
    },



    isBudgetApproved: function(budgetId) {
        var gr = new GlideRecord('Budget'); 
        if (gr.get(budgetId)) {
            return gr.u_status == 'approved'; 
        }
        return false;
    },


    getBudgetDetailsByEventId: function(eventId) {
        var budgets = [];
        var gr = new GlideRecord('Budget'); 
        gr.addQuery('u_event_id', eventId); 
        gr.query();
        while (gr.next()) {
            budgets.push(gr);
        }
        return budgets;
    },


    type: 'BudgetUtils'
};
